using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapRuins.EditorTools;
public static class RuinsImpactReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Shot(Camera c,Vector3 p,Vector3 target,string name){c.transform.position=p;c.transform.LookAt(target);var rt=new RenderTexture(960,720,24);c.targetTexture=rt;c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes("Evidence/"+name,t.EncodeToPNG());RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);}
 static void Views(GameObject root,Camera c,string prefix){var mats=root.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name!="TerrainCaps").Select(r=>(r,r.sharedMaterial)).ToArray();Shot(c,new Vector3(15,20,19),new Vector3(0,3,0),prefix+"-normal.png");Shot(c,new Vector3(3,6.5f,4),new Vector3(0,4.2f,0),prefix+"-stairs.png");var gray=new Material(Shader.Find("Universal Render Pipeline/Lit"));gray.SetColor("_BaseColor",new Color(.55f,.55f,.55f));gray.SetFloat("_Smoothness",.15f);foreach(var pair in mats)pair.r.sharedMaterial=gray;Shot(c,new Vector3(15,20,19),new Vector3(0,3,0),prefix+"-mono.png");Shot(c,new Vector3(3,5.4f,-7.2f),new Vector3(0,3.55f,-4.3f),prefix+"-mono-close.png");foreach(var pair in mats)pair.r.sharedMaterial=pair.sharedMaterial;UnityEngine.Object.DestroyImmediate(gray);}
 public static void Run(){try{
  EditorSceneManager.OpenScene("Assets/RuinsTarget25Output/Room.unity");var terrain=UnityEngine.Object.FindAnyObjectByType<Terrain>();var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();camera.orthographic=false;camera.backgroundColor=new Color(.075f,.085f,.1f);var B=GameObject.Find("ruins_1")?.transform.parent.gameObject;Check(B!=null,"B missing");Views(B,camera,"impact-B");B.SetActive(false);
  var args=Environment.GetCommandLineArgs();var path=args[Array.IndexOf(args,"-ruinsExportDir")+1];var data=RuinsStructureImporter.Preflight(Path.Combine(path,"A"),new HashSet<string>{"separateAuthoringV1","ruinsStructuresV1"});var A=RuinsStructureImporter.Build(data,terrain,"Assets/RuinsTarget25A");var ar=A.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name!="TerrainCaps").ToArray();Check(ar.Length==19,"A count");Check(ar.All(r=>r.GetComponent<MeshFilter>().sharedMesh==r.GetComponent<MeshCollider>().sharedMesh),"A collider sharing");UnityEngine.Object.DestroyImmediate(A);A=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget25A/Ruins.prefab"));Views(A,camera,"impact-A");
  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/RuinsTarget25A/Room.unity");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene("Assets/RuinsTarget25A/Room.unity");Check(GameObject.Find("ruins_1")!=null,"A Scene reload");
  File.WriteAllText("Evidence/impact-review.json","{\"AformalImportPrefabScene\":true,\"BformalImportPreviouslyVerified\":true,\"sameCameraLighting\":true,\"monochromeAndStairs\":true,\"player\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("Evidence/impact-failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
